function optionName(v) {
  if (
    v &&
    typeof v === 'object' &&
    !Array.isArray(v)
  ) {
    return v.name ?? String(v);
  }

  return String(v ?? '');
}

function multiNames(v) {
  if (!Array.isArray(v)) return [];
  return v.map(optionName).filter(Boolean);
}

function linkedRecordId(v) {
  if (
    v &&
    typeof v === 'object' &&
    !Array.isArray(v)
  ) {
    return String(v.id ?? '').trim();
  }

  return String(v ?? '').trim();
}

const out = [];

for (const item of $input.all()) {
  const t = item.json;

  const rawDialogs =
    Array.isArray(t.agent_dialogs_v3)
      ? t.agent_dialogs_v3
      : [];

  const dialogIds =
    rawDialogs
      .map(linkedRecordId)
      .filter(Boolean);

  for (const dialogRecordId of dialogIds) {
    out.push({
      json: {
        task_record_id: t.id,
        task_name: t.Name_task ?? '',
        dialog_record_id: dialogRecordId,

        timezone:
          optionName(t.timezone) ||
          'Europe/Moscow',

        work_days:
          multiNames(t.work_days).length
            ? multiNames(t.work_days)
            : ['Mon', 'Tue', 'Wed', 'Thu', 'Fri'],

        work_start:
          String(t.work_start ?? '09:00'),

        work_end:
          String(t.work_end ?? '19:00'),

        delay_min_sec:
          Number(t.delay_min_sec ?? 20),

        delay_max_sec:
          Number(t.delay_max_sec ?? 300)
      }
    });
  }
}

return out;

function sql(v) {
  return String(v ?? '').replace(/'/g, "''");
}
function hhmm(v, fallback) {
  const m = String(v || fallback).match(/^(\d{1,2}):(\d{2})/);
  if (!m) throw new Error(`Invalid time: ${v}`);
  return { h: Number(m[1]), m: Number(m[2]) };
}

const d = $json;
const cfg = $('Expand Task Dialogs').item.json;
function linkedId(v) {
  if (
    v &&
    typeof v === 'object' &&
    !Array.isArray(v)
  ) {
    return String(v.id ?? '').trim();
  }

  return String(v ?? '').trim();
}

const rawTask =
  Array.isArray(d.task)
    ? d.task[0]
    : d.task;

const taskId = linkedId(rawTask);

if (!d.id) throw new Error('Airtable dialog record id is missing');
if (!taskId) throw new Error(`Dialog ${d.id} is not linked to agent_tasks_v3`);
if (!d.telegram_username) throw new Error(`Dialog ${d.id} has no telegram_username`);

const zone = cfg.timezone || 'Europe/Moscow';
const now = $now.setZone(zone);
const start = hhmm(cfg.work_start, '09:00');
const end = hhmm(cfg.work_end, '19:00');

const dayMap = { Mon:1, Tue:2, Wed:3, Thu:4, Fri:5, Sat:6, Sun:7 };
const allowed = new Set((cfg.work_days || []).map(x => dayMap[x]).filter(Boolean));
if (!allowed.size) [1,2,3,4,5].forEach(x => allowed.add(x));

let min = Math.max(0, Math.floor(Number(cfg.delay_min_sec || 0)));
let max = Math.max(min, Math.floor(Number(cfg.delay_max_sec || min)));
const delay = min + Math.floor(Math.random() * (max - min + 1));

let runAt = null;

// Перебираем рабочие окна от вчерашнего дня до +8 дней.
// Это поддерживает и обычный график 09:00–19:00, и ночной 22:00–06:00.
for (let off = -1; off <= 8 && !runAt; off++) {
  const day = now.startOf('day').plus({ days: off });
  if (!allowed.has(day.weekday)) continue;

  let ws = day.set({ hour:start.h, minute:start.m, second:0, millisecond:0 });
  let we = day.set({ hour:end.h, minute:end.m, second:0, millisecond:0 });

  if (we <= ws) we = we.plus({ days: 1 });
  if (now >= we) continue;

  const base = now > ws ? now : ws;
  const candidate = base.plus({ seconds: delay });

  if (candidate < we) runAt = candidate;
}

if (!runAt) {
  throw new Error('Could not calculate next allowed work window');
}

const scheduledRunAt = runAt.toUTC().toISO();

const q = `
WITH upsert_dialog AS (
  INSERT INTO agent_v3.dialogs (
    airtable_dialog_id,
    airtable_task_id,
    person_name,
    person_role,
    telegram_username,
    status,
    next_action_at,
    metadata,
    updated_at
  )
  VALUES (
    '${sql(d.id)}',
    '${sql(taskId)}',
    NULLIF('${sql(d.person_name)}', ''),
    NULLIF('${sql(d.person_role)}', ''),
    '${sql(d.telegram_username)}',
    'scheduled',
    '${sql(scheduledRunAt)}'::timestamptz,
    jsonb_build_object('task_status','Active'),
    NOW()
  )
  ON CONFLICT (airtable_dialog_id)
  DO UPDATE SET
    airtable_task_id = EXCLUDED.airtable_task_id,
    person_name = EXCLUDED.person_name,
    person_role = EXCLUDED.person_role,
    telegram_username = EXCLUDED.telegram_username,
    metadata = jsonb_set(
      COALESCE(agent_v3.dialogs.metadata, '{}'::jsonb),
      '{task_status}',
      '"Active"'::jsonb,
      true
    ),
    status = CASE
      WHEN agent_v3.dialogs.status = 'new' THEN 'scheduled'
      ELSE agent_v3.dialogs.status
    END,
    next_action_at = CASE
      WHEN agent_v3.dialogs.status IN ('new','scheduled')
      THEN EXCLUDED.next_action_at
      ELSE agent_v3.dialogs.next_action_at
    END,
    updated_at = NOW()
  RETURNING id, airtable_dialog_id, airtable_task_id, next_action_at
),
create_event AS (
  INSERT INTO agent_v3.events (
    dialog_id,
    event_type,
    run_at,
    status,
    payload
  )
  SELECT
    ud.id,
    'start_dialog',
    '${sql(scheduledRunAt)}'::timestamptz,
    'pending',
    jsonb_build_object(
      'airtable_task_id', ud.airtable_task_id,
      'airtable_dialog_id', ud.airtable_dialog_id
    )
  FROM upsert_dialog ud
  WHERE NOT EXISTS (
    SELECT 1
    FROM agent_v3.events e
    WHERE e.dialog_id = ud.id
      AND e.event_type = 'start_dialog'
      AND e.status IN ('pending','processing','done')
  )
  RETURNING dialog_id
)
SELECT
  id AS dialog_db_id,
  airtable_dialog_id,
  airtable_task_id,
  next_action_at
FROM upsert_dialog;
`;

return [{
  json: {
    ...d,
    airtable_task_id: taskId,
    scheduled_run_at: scheduledRunAt,
    delay_sec: delay,
    sql_query: q
  }
}];

const out = [];

for (const item of $input.all()) {
  const d = item.json;

  let status = d.Status ?? d.status ?? '';

  if (
    status &&
    typeof status === 'object' &&
    !Array.isArray(status)
  ) {
    status = status.name ?? '';
  }

  status = String(status).trim().toLowerCase();

  // Task Watcher schedules only never-started dialogs.
  // Existing scheduled/active/waiting/done dialogs are left untouched.
  if (status !== 'new') {
    continue;
  }

  out.push(item);
}

return out;

