}

function optionName(v) {
  if (v && typeof v === 'object' && !Array.isArray(v)) {
    return v.name ?? '';
  }
  return String(v ?? '');
}

function hhmm(v, fallback) {
  const m = String(v || fallback).match(/^(\d{1,2}):(\d{2})/);
  if (!m) throw new Error(`Invalid time: ${v}`);
  return { h: Number(m[1]), m: Number(m[2]) };
}

function multiNames(v) {
  if (!Array.isArray(v)) return [];
  return v.map(optionName).filter(Boolean);
}

const t = $json;
const taskId = String(t.id ?? '').trim();

if (!taskId) {
  throw new Error('Active task Airtable id is missing');
}

const zone =
  optionName(t.timezone) ||
  'Europe/Moscow';

const now = $now.setZone(zone);

const start = hhmm(
  t.work_start,
  '09:00'
);

const end = hhmm(
  t.work_end,
  '19:00'
);

const dayMap = {
  Mon: 1,
  Tue: 2,
  Wed: 3,
  Thu: 4,
  Fri: 5,
  Sat: 6,
  Sun: 7
};

const workDays = multiNames(t.work_days);
const allowed = new Set(
  workDays
    .map(x => dayMap[x])
    .filter(Boolean)
);

if (!allowed.size) {
  [1, 2, 3, 4, 5].forEach(x => allowed.add(x));
}

let min = Math.max(
  0,
  Math.floor(Number(t.delay_min_sec ?? 20))
);

let max = Math.max(
  min,
  Math.floor(Number(t.delay_max_sec ?? 300))
);

const delay =
  min +
  Math.floor(
    Math.random() * (max - min + 1)
  );

let resumeAt = null;

// Find nearest allowed work window.
// Supports both day and overnight schedules.
for (
  let off = -1;
  off <= 8 && !resumeAt;
  off++
) {
  const day =
    now
      .startOf('day')
      .plus({ days: off });

  if (!allowed.has(day.weekday)) {
    continue;
  }

  let ws =
    day.set({
      hour: start.h,
      minute: start.m,
      second: 0,
      millisecond: 0
    });

  let we =
    day.set({
      hour: end.h,
      minute: end.m,
      second: 0,
      millisecond: 0
    });

  if (we <= ws) {
    we = we.plus({ days: 1 });
  }

  if (now >= we) {
    continue;
  }

  const base =
    now > ws
      ? now
      : ws;

  const candidate =
    base.plus({ seconds: delay });

  if (candidate < we) {
    resumeAt = candidate;
  }
}

if (!resumeAt) {
  throw new Error(
    'Could not calculate resume work window'
  );
}

const resumeIso =
  resumeAt
    .toUTC()
    .toISO();

const query = `
UPDATE agent_v3.events e
SET
  run_at =
    '${sql(resumeIso)}'::timestamptz,

  payload =
    (
      COALESCE(
        e.payload,
        '{}'::jsonb
      )
      - 'deferred_by_task_status'
      - 'deferred_original_run_at'
      - 'deferred_at'
    ),

  updated_at = NOW()

FROM agent_v3.dialogs d

WHERE
  e.dialog_id = d.id

  AND
  d.airtable_task_id =
    '${sql(taskId)}'

  AND
  e.status = 'pending'

  AND
  COALESCE(
    e.payload
      ->> 'deferred_by_task_status',
    ''
  ) = 'Paused'

RETURNING
  e.id AS event_id,
  e.dialog_id,
  e.event_type,
  e.run_at,
  e.status;
`;

return [{
  json: {
    ...t,
    task_record_id: taskId,
    resume_run_at: resumeIso,
    sql_query: query
  }
}];

