  d.airtable_task_id =
    '${sql(taskId)}'

  AND
  e.status = 'pending'

RETURNING
  e.id AS event_id,
  e.dialog_id,
  e.event_type,
  e.status;
`;

return [{
  json: {
    ...$json,
    task_record_id: taskId,
    sql_query: query
  }
}];

